import{_ as t,o as l,c as i,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"Beyond Particle Physics- The Impact of Ceph and OpenStack on CERNs Multi-D... E. Bocchi & J.C. Leon","description":"","frontmatter":{"title":"Beyond Particle Physics- The Impact of Ceph and OpenStack on CERNs Multi-D... E. Bocchi & J.C. Leon","date":"2025-01-26T00:00:00.000Z","updated":"2025-01-26T00:00:00.000Z","tags":["Ceph","OpenStack","CERN","Data Center","Storage Solutions"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Beyond_Particle_Physics_-_The_Impact_of_Ceph_and_OpenStack_on_CERN_s_Multi-D..._E._Bocchi_J.C._Leon.md","filePath":"posts/2025/Beyond_Particle_Physics_-_The_Impact_of_Ceph_and_OpenStack_on_CERN_s_Multi-D..._E._Bocchi_J.C._Leon.md","lastUpdated":1780459816000}'),o={name:"posts/2025/Beyond_Particle_Physics_-_The_Impact_of_Ceph_and_OpenStack_on_CERN_s_Multi-D..._E._Bocchi_J.C._Leon.md"};function _(n,e,p,s,c,r){return l(),i("div",null,[...e[0]||(e[0]=[a('<h3 id="会议纪要-cern的ceph与openstack集成及新数据中心介绍" tabindex="-1">会议纪要：CERN的Ceph与OpenStack集成及新数据中心介绍 <a class="header-anchor" href="#会议纪要-cern的ceph与openstack集成及新数据中心介绍" aria-label="Permalink to &quot;会议纪要：CERN的Ceph与OpenStack集成及新数据中心介绍&quot;">​</a></h3><p>CERN的SEF集群操作员Enrico和云技术负责人Jose在Auditorium C介绍了CERN的Ceph与OpenStack集成、新数据中心的构建与运营，以及跨数据中心的更高可用性存储方案。</p><h3 id="会议要点" tabindex="-1">会议要点： <a class="header-anchor" href="#会议要点" aria-label="Permalink to &quot;会议要点：&quot;">​</a></h3><ol><li><p><strong>CERN的背景与任务</strong>：</p><ul><li>CERN是全球最大的粒子物理实验室，运营大型强子对撞机（LHC），需要处理、存储和分发海量数据。</li><li>CERN的存储需求包括数据重建、存储、分发，以及备份和归档。</li></ul></li><li><p><strong>Ceph在CERN的应用</strong>：</p><ul><li>CERN使用Ceph作为后端存储，支持HPC集群、对象存储、块存储和文件系统存储。</li><li>Ceph用于存储加速器监控数据、探测器数据、备份和归档，以及全球数据分发。</li></ul></li><li><p><strong>OpenStack与Ceph的集成</strong>：</p><ul><li>CERN的云基础设施基于OpenStack，提供计算、存储和网络资源。</li><li>OpenStack与Ceph集成，支持虚拟机镜像、块存储（RBD）、文件共享（Manila）和对象存储（RADOS Gateway）。</li></ul></li><li><p><strong>新数据中心的构建</strong>：</p><ul><li>新数据中心的构建是为了应对LHC高亮度扩展带来的计算需求增长。</li><li>新数据中心设计时考虑了物理基础设施的优化，采用了高密度的JBOD、NVMe存储和AMD单插槽处理器。</li></ul></li><li><p><strong>跨数据中心的更高可用性存储方案</strong>：</p><ul><li>CERN正在探索RGW Multisite和Ceph Stretch Clusters，以实现跨数据中心的存储一致性。</li><li>CERN正在招聘一名初级存储工程师，专注于AIML工作负载。</li></ul></li><li><p><strong>Ceph元数据管理的挑战</strong>：</p><ul><li>CERN的Ceph集群管理了数十亿个iNode，元数据管理面临挑战。</li><li>CERN正在探索Emerald pinning和多文件系统（Multi FS）解决方案。</li></ul></li><li><p><strong>用户界面与可用性改进</strong>：</p><ul><li>CERN正在简化用户界面，隐藏底层基础设施复杂性。</li></ul></li><li><p><strong>未来工作与社区合作</strong>：</p><ul><li>CERN希望通过社区合作，分享经验并学习其他Ceph运营商的最佳实践。</li></ul></li></ol><h3 id="决定事项与后续行动计划" tabindex="-1">决定事项与后续行动计划： <a class="header-anchor" href="#决定事项与后续行动计划" aria-label="Permalink to &quot;决定事项与后续行动计划：&quot;">​</a></h3><ol><li>继续优化Ceph元数据管理。</li><li>完善RGW Multisite和Stretch Clusters的监控与故障切换机制。</li><li>简化用户界面。</li><li>招聘新成员，专注于AIML工作负载。</li></ol><h3 id="会议总结" tabindex="-1">会议总结： <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结：&quot;">​</a></h3><p>本次会议详细介绍了CERN如何利用Ceph和OpenStack构建大规模存储解决方案，并讨论了新数据中心的构建和跨数据中心存储的一致性等问题。会议还强调了Ceph元数据管理的挑战以及CERN在用户界面和可用性改进方面的努力。</p>',8)])])}const u=t(o,[["render",_]]);export{C as __pageData,u as default};
